contract_clause_fact(contrato_ocs_261_2020, clausula_setima_pagamento, prazo_apresentacao_documento, 'dia 25 do mês', 'Parágrafo Primeiro').
contract_clause_fact(contrato_ocs_261_2020, clausula_setima_pagamento, informacoes_documento, ['número da Ordem de Compra/Serviço – OCS', 'número SAP do Contrato', 'número do pedido SAP', 'número da Folha de Registro de Serviços (FRS)', 'descrição detalhada do objeto executado e dos respectivos valores', 'período de referência da execução do objeto', 'nome e número do CNPJ da CONTRATADA', 'nome, telefone e e-mail do responsável pelo documento fiscal ou equivalente legal', 'nome e número do banco e da agência, bem como o número da conta corrente da CONTRATADA', 'tomador do serviço: Banco Nacional de Desenvolvimento Econômico e Social – BNDES', 'CNPJ do tomador do serviço: 33.657.248/0001-89', 'local de execução do objeto', 'código do serviço', 'número de inscrição do contribuinte individual válido junto ao INSS (NIT ou PIS/PASEP)'], 'Parágrafo Quarto').
contract_clause_fact(contrato_ocs_261_2020, clausula_setima_pagamento, retencoes_tributarias, 'nos termos da legislação tributária', 'Parágrafo Sétimo').
